import { analyzeImage, optimizePattern, refineScrapMask } from './vision.js';
import { recommendProducts } from './recommend.js';
let analysis;
self.onmessage=({data})=>{try{if(data.type==='analyze')analysis=analyzeImage(data.imageData,{sceneWidthCm:data.sceneWidthCm});if(!analysis)throw Error('Analyze a fabric photo first.');if(data.type==='refine')analysis=refineScrapMask(analysis,data.scrapId,data.foregroundMask,data.modelProvenance);const scraps=analysis.scraps.filter(s=>!(data.excludedIds||[]).includes(s.id));if(data.type==='recommend'){self.postMessage({requestId:data.requestId,recommendations:recommendProducts(scraps,data.options||{})});return;}const plan=optimizePattern(scraps,data.options||{});plan.excludedScrapIds=data.excludedIds||[];self.postMessage({requestId:data.requestId,analysis:['analyze','refine'].includes(data.type)?analysis:null,plan});}catch(error){self.postMessage({requestId:data.requestId,error:error.message});}};
